#include <iostream>
#include <iomanip>
#include <cstdint>

// Giai quyet Bai 10, 11, 28: Khai niem Union tach byte
union WordInspector {
    uint16_t value;
    struct {
        uint8_t low;
        uint8_t high;
    } bytes;
};

int main() {
    WordInspector w;
    w.value = 0xABCD;

    std::cout << "Full Value: 0x" << std::hex << std::uppercase << w.value << "\n";
    std::cout << "Low Byte  : 0x" << static_cast<int>(w.bytes.low) << "\n";
    std::cout << "High Byte : 0x" << static_cast<int>(w.bytes.high) << "\n";

    // Minh hoa Bai 11: Khoi tao {{1, 2}}
    WordInspector w2 = {};
    w2.bytes.low = 1;
    w2.bytes.high = 2;
    std::cout << "Value from bytes {1, 2}: " << std::dec << w2.value << "\n";
    return 0;
}

#include <iostream>

struct CharNode {
    char data;
    CharNode* next;
};

void printList(const CharNode* head) {
    for (const CharNode* cur = head; cur != nullptr; cur = cur->next) {
        std::cout << cur->data << (cur->next ? " -> " : "\n");
    }
}

int main() {
    // Tao danh sach tu 'A' den 'P' (minh hoa cho A..Z)
    CharNode* head = nullptr;
    CharNode* tail = nullptr;
    for (char c = 'A'; c <= 'P'; ++c) {
        auto* n = new CharNode{c, nullptr};
        if (!head) head = n;
        else tail->next = n;
        tail = n;
    }

    std::cout << "Original list: ";
    printList(head);

    // Dao phan tu A..D xuong cuoi (tach tai 'D')
    char splitChar = 'D';
    CharNode* splitNode = head;
    while (splitNode && splitNode->data != splitChar) {
        splitNode = splitNode->next;
    }

    if (splitNode && splitNode->next) {
        CharNode* newHead = splitNode->next;
        splitNode->next = nullptr;
        tail->next = head;
        head = newHead;
    }

    std::cout << "After rotation: ";
    printList(head);

    // Giai phong bo nho
    while (head) {
        CharNode* tmp = head->next;
        delete head;
        head = tmp;
    }
    return 0;
}

#include <iostream>

struct Person {
    int id;
    Person* next;
};

int main() {
    const int N = 30;
    const int K = 7;

    // Xay dung vong 30 nguoi
    Person* head = new Person{1, nullptr};
    Person* prev = head;
    for (int i = 2; i <= N; ++i) {
        Person* p = new Person{i, nullptr};
        prev->next = p;
        prev = p;
    }
    prev->next = head; // Noi thanh vong tron

    Person* cur = head;
    Person* beforeCur = prev;

    // Loai lan luot cho den khi con 1 nguoi
    while (cur->next != cur) {
        // Dem K-1 buoc
        for (int step = 1; step < K; ++step) {
            beforeCur = cur;
            cur = cur->next;
        }
        // cur bay gio la nguoi thu K bi loai
        beforeCur->next = cur->next;
        Person* toDelete = cur;
        cur = cur->next;
        delete toDelete;
    }

    std::cout << "Survivor ID: " << cur->id << "\n";
    delete cur;
    return 0;
}
